package main

import (
	"fmt"
	"os"
	"path/filepath"

	"github.com/gzhysuiioo/payflow-settlement/payflow"
)

func amt(v int64) *int64 { return &v }
func lim(v int64) *int64 { return &v }

func main() {
	path := filepath.Join(os.TempDir(), "readme-submit-example-ledger.json")
	_ = os.Remove(path)
	defer os.Remove(path)

	if err := payflow.CreateLedger(path, []payflow.BalanceInit{
		{Account: "aa-1", Asset: "usdc", Balance: 100},
	}); err != nil {
		panic(err)
	}

	l, err := payflow.Open(path)
	if err != nil {
		panic(err)
	}
	defer l.Close()

	res, err := l.Submit(payflow.FeeBatch{
		FeeBps: 1000,
		Limits: []payflow.ChargeLimit{
			{Account: "aa-1", Asset: "usdc", MaxCharged: lim(88)},
		},
		Intents: []payflow.PaymentIntent{
			{ID: "p1", Account: "aa-1", Paymaster: "pm-1", Asset: "usdc", Amount: amt(60)},
			{ID: "p1", Account: "aa-1", Paymaster: "pm-1", Asset: "usdc", Amount: amt(60)},
			{ID: "p2", Account: "aa-1", Paymaster: "pm-1", Asset: "usdc", Amount: amt(30)},
			{ID: "p2", Account: "aa-1", Paymaster: "pm-1", Asset: "usdc", Amount: amt(20)},
		},
	})
	if err != nil {
		panic(err)
	}

	for _, r := range res.Results {
		switch r.Status {
		case payflow.StatusSettled, payflow.StatusDuplicate:
			fmt.Printf("%s: %s amount=%d fee=%d charged=%d seq=%d\n",
				r.ID, r.Status, r.Record.Amount, r.Record.Fee, r.Record.Charged, r.Record.Seq)
		default:
			fmt.Printf("%s: %s reason=%q record=%v\n", r.ID, r.Status, r.Reason, r.Record)
		}
	}

	snap, err := l.Query()
	if err != nil {
		panic(err)
	}
	fmt.Printf("balance: %d\n", snap.Balances[0].Balance)
	fmt.Printf("history: %d record(s)\n", len(snap.Settlements))
	for _, r := range snap.Settlements {
		fmt.Printf("  %s amount=%d fee=%d charged=%d\n", r.ID, r.Amount, r.Fee, r.Charged)
	}

	// 整批错误的读取方式
	_, err = l.Submit(payflow.FeeBatch{FeeBps: 10001})
	if le, ok := err.(*payflow.LedgerError); ok {
		fmt.Printf("batch error: kind=%s message=%q\n", le.Kind, le.Message)
	}
}

