	// 在尚未占用的路径初始化：只用一个账户的一种资产，余额 100。
	path := filepath.Join(os.TempDir(), "payflow-submit-example.json")
	_ = os.Remove(path) // 仅为让示例可重复运行；真实程序不要删除已有账本
